package com.vajjha.recipes.repository;import com.vajjha.recipes.model.Recipe;import org.springframework.data.jpa.repository.JpaRepository;import java.util.List;import java.util.Optional;public interface RecipeRepository extends JpaRepository<Recipe,Long>{Optional<Recipe>findByRequestKey(String requestKey);List<Recipe>findAllByOrderByCreatedAtDesc();List<Recipe>findByCategoryIdOrderByCreatedAtDesc(Long categoryId);}